challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "dns is the source of the P-CSCF INVITE rate spikes and UPF GTP-U rate drops, as the container exit breaks name resolution for IMS signaling components.",
      "primary_suspect_nf": "dns",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the status of the dns container",
          "expected_if_hypothesis_holds": "The dns container state is exited, down, or not running.",
          "falsifying_observation": "The dns container state is Up and healthy.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "container='pcscf', target_ip='172.22.0.15'",
          "expected_if_hypothesis_holds": "100% packet loss indicating the dns container is unresponsive or down.",
          "falsifying_observation": "0% packet loss and normal latency, indicating the dns container is alive and reachable from pcscf.",
          "conflates_with": [
            "routing failure or network partition between pcscf and dns",
            "pcscf network interface failure"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "container='smf', target_ip='172.22.0.15'",
          "expected_if_hypothesis_holds": "100% packet loss, confirming the dns container is globally unresponsive rather than a localized pcscf path issue.",
          "falsifying_observation": "0% packet loss, indicating the dns container is reachable from smf and the failure is isolated to the path from pcscf.",
          "conflates_with": []
        }
      ],
      "notes": "Hypothesis explicitly claims the dns container exited. get_network_status directly verifies container state. measure_rtt probes test reachability per the KB-authored liveness check, using smf as a compositional partner to disambiguate a pcscf-specific network path failure from a global dns container failure."
    }
  ]
}
